from itertools import combinations
pts = {'A':(0,10),'B':(-10,0),'C':(10,0),'O':(0,5)}
segs = [('A','B'),('B','C'),('A','C'),('O','A'),('O','B'),('O','C')]
def on_line(p,q,r):
    (x1,y1),(x2,y2),(x3,y3)=pts[p],pts[q],pts[r]; return (x2-x1)*(y3-y1)-(y2-y1)*(x3-x1)==0
edges = {frozenset(s) for s in segs}
cnt = sum(1 for t in combinations(pts,3) if all(frozenset(e) in edges for e in combinations(t,2)) and not on_line(*t))
opts = {'A':5,'B':4,'C':2,'D':3}
assert cnt == opts['B']
for k in 'ACD': assert cnt != opts[k]
